mapper.update:
update seckill_activity
name = #{name}, dish_id = #{dishId}, seckill_price = #{seckillPrice}, total_stock = #{totalStock}, sold_stock = #{soldStock}, per_user_limit = #{perUserLimit}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select
from seckill_activity a left join dish d on a.dish_id = d.id
and a.name like concat('%', #{name}, '%')
and a.status = #{status}
and a.dish_id = #{dishId}
order by a.status asc, a.start_time desc
